spec.setup_code:
var INK='#04204B',SEC='#3D5F91',GUIDE='#8098BC',BLUE='#0B4FC0',TEAL='#138374',WARM='#B4552F';
var PERIOD=24;
var KT=[-10,0,60,900],KX=[0,0.07,0.55,1];
var AK=[0,1.5,4,9,14,19,24],AT=[-10,0,1,30,300,900,900];
function interp(v,A,B){if(v<=A[0])return B[0];for(var i=1;i<A.length;i++){if(v<=A[i]){var u=(v-A[i-1])/(A[i]-A[i-1]);return B[i-1]+u*(B[i]-B[i-1]);}}return B[B.length-1];}
function sm(a,b,t){var u=Math.max(0,Math.min(1,(t-a)/(b-a)));return u*u*(3-2*u);}
function dev(t){if(t<0)return 0;if(t<10)return 0.15*Math.sin(Math.PI/2*t/10);if(t<30)return 0.15-0.05*sm(10,30,t);return 0.10*(1-sm(30,300,t));}
function powers(t){if(t<0)return [0,0,0];var s1=sm(30,300,t),s2=sm(300,750,t);var r=sm(0,30,t);var fcr=3000*r*(1-s1)*(1-s2);var m=3000*s2;var a=3000*s1*(1-s2);return [fcr,a,m];}
function wrap(ctx,text,maxW){var words=text.split(' '),lines=[],cur='';for(var i=0;i<words.length;i++){var t=cur?cur+' '+words[i]:words[i];if(ctx.measureText(t).width>maxW&&cur){lines.push(cur);cur=words[i];}else cur=t;}lines.push(cur);return lines;}
var PH=[
{h:'Steady state: 50.00 Hz',c:INK,t:'Generation and load are balanced before the incident.'},
{h:'Phase 1 (0-1 s): Loss of 3 GW',c:WARM,t:'Inertia of spinning machines slows the fall (rate of change of frequency).'},
{h:'Phase 2 (1-30 s): FCR, frequency containment reserve',c:BLUE,t:'FCR: shared across Continental Europe, ~3,000 MW, fully active at 200 mHz deviation within 30 s; every country holds a share.'},
{h:'Phase 3 (30 s - 5 min): aFRR, automatic frequency restoration reserve',c:TEAL,t:'aFRR: activated by the TSO\'s controller, full within 5 min. FCR ramps down as frequency returns to 50.00 Hz.'},
{h:'Phase 4 (5-15 min): mFRR, manual frequency restoration reserve',c:WARM,t:'mFRR: full within 12.5 min. It replaces aFRR, which is freed for the next event.'},
{h:'Phase 5: settlement',c:INK,t:'mFRR: full within 12.5 min, aFRR is freed for the next event. After that, the balancing group responsible pays the imbalance price.'}];
return {draw:function(ctx,width,height,time,dt){
ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);
var a=time%PERIOD;var tc=interp(a,AK,AT);
var L=62,R=width-16,pw=R-L;
var y1=Math.round(height*0.09),y1b=Math.round(height*0.36);
var y2=Math.round(height*0.46),y2b=Math.round(height*0.73);
function X(t){return L+pw*interp(t,KT,KX);}
function YF(f){return y1+(50.05-f)/0.30*(y1b-y1);}
function YP(p){return y2b-p/3000*(y2b-y2);}
var xc=X(tc);
ctx.font='12px sans-serif';ctx.textBaseline='alphabetic';
ctx.lineWidth=1;ctx.strokeStyle=GUIDE;ctx.fillStyle=SEC;ctx.textAlign='right';
var fs=[49.75,49.80,49.85,49.90,49.95,50.00,50.05];
var i;
for(i=0;i<fs.length;i++){ctx.globalAlpha=(Math.abs(fs[i]-50)<1e-6)?0.9:0.3;ctx.beginPath();ctx.moveTo(L,YF(fs[i]));ctx.lineTo(R,YF(fs[i]));ctx.stroke();ctx.globalAlpha=1;ctx.fillText(fs[i].toFixed(2),L-6,YF(fs[i])+4);}
var ps=[0,1000,2000,3000];
for(i=0;i<ps.length;i++){ctx.globalAlpha=0.3;ctx.beginPath();ctx.moveTo(L,YP(ps[i]));ctx.lineTo(R,YP(ps[i]));ctx.stroke();ctx.globalAlpha=1;ctx.fillText(String(ps[i]),L-6,YP(ps[i])+4);}
ctx.textAlign='left';ctx.fillText('f in Hz',4,y1-6);ctx.fillText('P in MW',4,y2-6);
var dv=[30,300,750];ctx.setLineDash([3,4]);ctx.globalAlpha=0.5;
for(i=0;i<dv.length;i++){ctx.beginPath();ctx.moveTo(X(dv[i]),y1);ctx.lineTo(X(dv[i]),y2b);ctx.stroke();}
ctx.setLineDash([]);ctx.globalAlpha=1;
ctx.strokeStyle=INK;ctx.lineWidth=1.2;
ctx.beginPath();ctx.moveTo(L,y1);ctx.lineTo(L,y1b);ctx.lineTo(R,y1b);ctx.stroke();
ctx.beginPath();ctx.moveTo(L,y2);ctx.lineTo(L,y2b);ctx.lineTo(R,y2b);ctx.stroke();
var tk=[-10,0,10,30,60,300,600,900],tl=['-10 s','0','10 s','30 s','1 min','5 min','10 min','15 min'];
ctx.fillStyle=SEC;ctx.textAlign='center';
for(i=0;i<tk.length;i++){ctx.beginPath();ctx.moveTo(X(tk[i]),y2b);ctx.lineTo(X(tk[i]),y2b+4);ctx.stroke();ctx.fillText(tl[i],X(tk[i]),y2b+17);}
ctx.beginPath();var bx=X(60);ctx.moveTo(bx+9,y2b-5);ctx.lineTo(bx+15,y2b+5);ctx.moveTo(bx+13,y2b-5);ctx.lineTo(bx+19,y2b+5);ctx.stroke();
ctx.textAlign='right';ctx.fillText('time (axis stretched for the first minute)',R,y2b+31);
var lg=[['FCR',BLUE],['aFRR',TEAL],['mFRR',WARM]];ctx.textAlign='left';var lx=L;var ly=y2-10;
for(i=0;i<3;i++){ctx.fillStyle=lg[i][1];ctx.fillRect(lx,ly-9,12,10);ctx.fillStyle=INK;ctx.fillText(lg[i][0],lx+16,ly);lx+=70;}
ctx.fillStyle=SEC;ctx.fillText('stacked power supplied',lx+4,ly);
var px,t,p,c0,c1,k,cols=[BLUE,TEAL,WARM];
var PXS=[L,L+pw*0.07,L+pw*0.55,L+pw];
for(px=L;px<=xc;px+=2){t=interp(px,PXS,KT);if(t<0)continue;p=powers(t);c0=0;ctx.globalAlpha=0.85;
for(k=0;k<3;k++){c1=c0+p[k];if(p[k]>0.5){ctx.fillStyle=cols[k];ctx.fillRect(px,YP(c1),2.5,YP(c0)-YP(c1)+0.5);}c0=c1;}ctx.globalAlpha=1;}
ctx.strokeStyle=INK;ctx.lineWidth=2.2;ctx.beginPath();
var first=true,yy;for(px=L;px<=xc;px+=2){t=interp(px,PXS,KT);yy=YF(50-dev(t));if(first){ctx.moveTo(px,yy);first=false;}else ctx.lineTo(px,yy);}
ctx.lineTo(xc,YF(50-dev(tc)));ctx.stroke();
if(tc>=0){var x00=X(0);var pulse=1+0.35*Math.sin(a*6);ctx.strokeStyle=WARM;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x00,y1);ctx.lineTo(x00,y2b);ctx.stroke();
ctx.fillStyle=WARM;ctx.beginPath();ctx.arc(x00,YF(50),(tc<3?5*pulse:5),0,Math.PI*2);ctx.fill();
ctx.textAlign='left';ctx.fillText('outage: -3,000 MW',x00+6,y1+12);
ctx.setLineDash([5,4]);ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x00,YP(3000));ctx.lineTo(R,YP(3000));ctx.stroke();ctx.setLineDash([]);
ctx.fillStyle=WARM;ctx.textAlign='right';ctx.fillText('3,000 MW lost',R,YP(3000)+14);}
ctx.fillStyle=INK;
if(tc>=10){ctx.textAlign='right';ctx.fillText('nadir ~ 49.85 Hz',X(10)+30,YF(49.85)+16);}
if(tc>=30){ctx.textAlign='left';ctx.fillText('quasi-steady 49.90 Hz',X(30)+8,YF(49.90)+16);}
if(tc>=400){ctx.textAlign='left';ctx.fillText('50.00 Hz restored',X(400),YF(50)-6);}
ctx.strokeStyle=GUIDE;ctx.lineWidth=1;ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(xc,y1);ctx.lineTo(xc,y2b);ctx.stroke();ctx.setLineDash([]);
var ph=0;if(tc>=899.5&&a>=19.2)ph=5;else if(tc>=300)ph=4;else if(tc>=30)ph=3;else if(tc>=1)ph=2;else if(tc>=0)ph=1;
var P=PH[ph];ctx.font='bold 13px sans-serif';ctx.fillStyle=P.c;ctx.textAlign='left';
ctx.fillText(P.h,L,18);
ctx.font='12px sans-serif';ctx.fillStyle=SEC;ctx.textAlign='right';
var ts=tc<60?'t = '+tc.toFixed(1)+' s':'t = '+(tc/60).toFixed(1)+' min';
ctx.fillText(ts+'   f = '+(50-dev(tc)).toFixed(3)+' Hz',R,height-6);
ctx.font='12px sans-serif';ctx.textAlign='left';
var lines=wrap(ctx,P.t,pw+20);var ty=Math.round(height*0.73)+50;
ctx.fillStyle=P.c;ctx.fillRect(L-30,ty-11,3,lines.length*15);
ctx.fillStyle=INK;
for(i=0;i<lines.length;i++)ctx.fillText(lines[i],L-22,ty+i*15);
}};
